    val title get()=tr(titleKey)
    val description get()=tr(detailKey)
    /** Bundled faces for headlines and running text; ThemeLanguage themes use one face for both. */
    val headFace:String? get()=headFont ?: typefaceId
    val bodyFace:String? get()=bodyFont ?: typefaceId
    val glassOpacity get()=when {
        this in setOf(OS_WIN_7,OS_IOS_GLASS,OS_MAC_LEOPARD)->.76f
        this==OS_MAC_AQUA->.90f
        this==DECADE_00->.88f
        this==AURORA_VEIL->.84f
        this==PRISM_STUDIO->.86f
        texture==ThemeTexture.GLASS->if(dark).9f else .88f
        // Glass languages need translucent planes over their colour glows.
        language==DesignLanguage.GLASS->if(dark).80f else .74f
        else->1f
    }
}
