/** SQUIRCLE: continuous (superelliptic) corners. PEBBLE: four unequal radii (ThemeLanguage themes).
 * LEAF: organic leaf corners, PIXEL: stepped pixel corners, SHARP: right angles (DesignLanguage themes).
 * Material shapes stay convex, so platform shadows, clipping and hit areas behave like the rounded rectangle. */
enum class ThemeShape { ROUNDED, CUT, ASYMMETRIC, BEVEL, SQUIRCLE, PEBBLE, LEAF, PIXEL, SHARP }
enum class ThemeFont { SANS, SERIF, MONO, ROUNDED }
fun themeDark(settings: AppSettings,systemDark: Boolean): Boolean = settings.appTheme?.dark ?: when(settings.themeMode) {
    ThemeMode.SYSTEM->systemDark;ThemeMode.LIGHT->false;else->true
}
